// Native / direct-browser WASM equivalence for browser-painter admission
// (#1007; spec/design/browser-wasm.md "Painter admission"). Each compact recipe
// in tests/fixtures/painter_admission_cross_host.json (generated by
// crates/xyg-wasm/tests/painter_admission_parity.rs) is rebuilt through the
// Rust-backed sceneBatchEncode, then lowered by the native C ABI (koffi) and by
// the real wasm32 artifact (packages/xy-client/dist/xyg-wasm.wasm) under the
// same byte budget. Both must publish identical painter bytes or reject with
// the same stable scene::PainterRejection diagnostic and no painter output.
//
// Build the artifact with `node js/build.mjs && npm run build:wasm`.
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import test from "node:test";
import { fileURLToPath } from "node:url";

import { sceneBatchEncode, sceneBrowserPainter } from "../src/scene.js";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../../..");
const FIXTURE = JSON.parse(fs.readFileSync(path.join(ROOT, "tests/fixtures/painter_admission_cross_host.json"), "utf8"));
const WASM = path.join(ROOT, "packages/xy-client/dist/xyg-wasm.wasm");
const skip = fs.existsSync(WASM) ? false : "build the WASM artifact first: node js/build.mjs && npm run build:wasm";
const sha256 = (bytes) => createHash("sha256").update(bytes).digest("hex");

function scene(entry) {
  const { recipe } = FIXTURE;
  const n = entry.count;
  let bytes = sceneBatchEncode({
    viewport: recipe.viewport,
    margins: recipe.margins,
    xAxis: recipe.x_axis,
    yAxis: recipe.y_axis,
    kinds: new Uint8Array(n).fill(entry.kind),
    stableIds: BigUint64Array.from({ length: n }, (_, index) => BigInt(entry.distinct_ids ? index : 7)),
    styleRefs: new Uint32Array(n).fill(recipe.style_ref),
    styles: [{ fillRgba: recipe.style.fill_rgba, strokeRgba: recipe.style.stroke_rgba, strokeWidth: recipe.style.stroke_width }],
    diameter: new Float64Array(n).fill(entry.diameter),
    symbols: Uint8Array.from({ length: n }, (_, index) => (entry.alternate_symbols ? index % 2 : 0)),
    x0: new Float64Array(n).fill(recipe.x0),
    y0: new Float64Array(n).fill(recipe.y0),
    x1: new Float64Array(n).fill(recipe.x1),
    y1: new Float64Array(n).fill(recipe.y1),
  });
  if (entry.mutation === "truncate_last_byte") bytes = bytes.slice(0, -1);
  else if (entry.mutation === "next_scene_version") {
    bytes = bytes.slice();
    new DataView(bytes.buffer, bytes.byteOffset).setUint32(4, FIXTURE.scene_version + 1, true);
  } else assert.equal(entry.mutation, "none");
  return bytes;
}

async function loadWasm() {
  const { instance } = await WebAssembly.instantiate(fs.readFileSync(WASM), {});
  const x = instance.exports;
  return (bytes, maxBytes) => {
    const handle = x.xyg_wasm_instance_new(maxBytes);
    assert.ok(handle > 0, "WASM instance");
    try {
      assert.equal(x.xyg_wasm_arena_resize(handle, bytes.byteLength), 0);
      new Uint8Array(x.memory.buffer, x.xyg_wasm_arena_ptr(handle) >>> 0, bytes.byteLength).set(bytes);
      const status = x.xyg_wasm_scene_prepare(handle, 1, 0, bytes.byteLength);
      const outLen = x.xyg_wasm_output_len(handle) >>> 0;
      const output = new Uint8Array(x.memory.buffer, x.xyg_wasm_output_ptr(handle) >>> 0, outLen).slice();
      const errorLen = x.xyg_wasm_last_error_len(handle) >>> 0;
      const error = new TextDecoder().decode(new Uint8Array(x.memory.buffer, x.xyg_wasm_last_error_ptr(handle) >>> 0, errorLen));
      assert.equal(x.xyg_wasm_arena_len(handle) >>> 0, 0, "staging released");
      return { status, output, error };
    } finally {
      assert.equal(x.xyg_wasm_instance_dispose(handle), 0);
    }
  };
}

test("native and real wasm32 hosts agree on every painter admission case", { skip }, async () => {
  assert.equal(FIXTURE.schema, "xyg.painter-admission-cross-host/v1");
  const wasm = await loadWasm();
  for (const entry of FIXTURE.cases) {
    const bytes = scene(entry);
    assert.equal(bytes.byteLength, entry.scene_bytes, entry.name);
    assert.equal(sha256(bytes), entry.scene_sha256, `${entry.name}: Rust encoder bytes`);
    const browser = wasm(bytes, entry.max_bytes);
    if (entry.outcome === "ok") {
      const painter = sceneBrowserPainter(bytes, entry.max_bytes);
      assert.equal(painter.byteLength, entry.painter_bytes, entry.name);
      assert.equal(sha256(painter), entry.painter_sha256, entry.name);
      assert.equal(new DataView(painter.buffer, painter.byteOffset).getUint32(20, true), entry.traces, entry.name);
      assert.equal(browser.status, 0, `${entry.name}: ${browser.error}`);
      assert.deepEqual(browser.output, painter, `${entry.name}: native and WASM painter bytes`);
      continue;
    }
    assert.throws(() => sceneBrowserPainter(bytes, entry.max_bytes), (error) => {
      assert.ok(error instanceof RangeError);
      assert.equal(error.code, entry.code, entry.name);
      assert.equal(error.message, entry.diagnostic, entry.name);
      return true;
    });
    assert.equal(browser.status, entry.wasm_status, entry.name);
    assert.equal(browser.output.byteLength, 0, `${entry.name}: no partial WASM painter`);
    assert.equal(browser.error, entry.diagnostic, `${entry.name}: same diagnostic as native`);
  }
});
